```javascript
'use strict';
// Nightly. Writes exports/rating-summary.json: for each agent, how many ratings their tickets received in the
// past seven days, and the average score.
const fs = require('node:fs');
const path = require('node:path');
const { EXPORT_DIR } = require('./export-tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function summarizeRatings(store, { dir = EXPORT_DIR, now = new Date() } = {}) {
  const totals = new Map();
  for (const r of store.listRatings()) {
    if (!r.agent_id) continue;
    if (now.getTime() - new Date(r.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
    const agent = totals.get(r.agent_id) || { agent_id: r.agent_id, ratings: 0, sum: 0 };
    agent.ratings += 1;
    agent.sum += r.score;
    totals.set(r.agent_id, agent);
  }
  const rows = [...totals.values()]
    .map(({ agent_id, ratings, sum }) => ({ agent_id, ratings, average_score: Math.round((sum / ratings) * 100) / 100 }))
    .sort((a, b) => a.agent_id - b.agent_id);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'rating-summary.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, agents: rows.length };
}

module.exports = { summarizeRatings, WINDOW_DAYS };
```

